            }
            set_clause = ", ".join(f"{c}=?" for c in order_cols)
            cur.execute(
                f"UPDATE orders SET {set_clause} WHERE order_id=?",
                (*order_cols.values(), oid),
            )
            if cur.rowcount == 0:
                # Insert new order with sensible defaults for CS columns
                insert_cols = {
                    "order_id": oid,
