                    "shipping_status": "pending",
                    **order_cols,
                }
                col_names = ", ".join(insert_cols.keys())
                placeholders = ", ".join("?" for _ in insert_cols)
                cur.execute(
                    f"INSERT INTO orders ({col_names}) VALUES ({placeholders})",
